public class ConnectionDto { private Long id,tenantId,assignedToUserId; private String firstName,lastName,email,phone,companyName; private Connection.Source source; private Connection.Status status; private LocalDateTime createdAt,updatedAt; public Long getId(){return id;}public void setId(Long v){id=v;}public Long getTenantId(){return tenantId;}public void setTenantId(Long v){tenantId=v;}public Long getAssignedToUserId(){return assignedToUserId;}public void setAssignedToUserId(Long v){assignedToUserId=v;}public String getFirstName(){return firstName;}public void setFirstName(String v){firstName=v;}public String getLastName(){return lastName;}public void setLastName(String v){lastName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getCompanyName(){return companyName;}public void setCompanyName(String v){companyName=v;}public Connection.Source getSource(){return source;}public void setSource(Connection.Source v){source=v;}public Connection.Status getStatus(){return status;}public void setStatus(Connection.Status v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}public LocalDateTime getUpdatedAt(){return updatedAt;}public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
